<template>
 <div class="compatibility-page" :aria-busy="busy">
  <PageHead title="兼容性管理" desc="维护一次商品适用资料，在设备查询和权益包中复用。"><el-button v-if="returnTo" :disabled="busy" @click="router.push(returnTo)">返回选购 / 来源</el-button></PageHead>
  <el-radio-group :model-value="view" @change="changeView(String($event))"><el-radio-button value="products">商品适用台账</el-radio-button><el-radio-button value="device">按设备查询</el-radio-button></el-radio-group>
  <div v-if="view==='products'" class="workspace">
   <aside class="panel catalogue"><CatalogScopeTree :categories="store.data.categories" :types="index.typeRows" :category-id="category" :scope-type-id="typeId" :expanded-ids="expanded" @expand="expanded=$event" @select="category=$event;typeId=''" @select-type="typeId=$event;category=''"/>
    <el-input v-model="search" clearable placeholder="搜索商品、SKU、规格、产品类型" aria-label="搜索维护商品"/>
    <div class="ledger-tools"><el-switch v-model="includeDevices" active-text="显示设备与其他商品"/><span class="muted">{{products.length}} 个销售 SKU</span></div>
    <div class="product-list"><section v-for="group in productGroups" :key="group.id"><div class="spu-heading"><strong>{{group.name}}</strong><el-button v-if="group.rows.length>1" link @click="choose(group.rows.map(r=>r.id))">选择本组 SKU</el-button></div><button v-for="r in group.rows" :key="r.id" type="button" class="product-row" :class="{selected:ids.includes(r.id)}" :data-compat-product="r.id" @click="choose([r.id])"><strong>{{r.name}}</strong><span>{{r.spec||r.code}}</span><span class="row-meta">{{r.typeName}} · {{r.status}}<span v-if="r.confirmed"> · 已确认 {{r.confirmed}} 个型号</span><span v-if="r.pending"> · 待核验 {{r.pending}} 条</span><span v-if="!r.count"> · 未维护</span><span v-if="r.invalid"> · 引用待修复</span><span v-if="r.conflict"> · 资料冲突</span></span></button></section><el-empty v-if="!products.length" description="没有匹配商品，未维护关系的商品也会列在这里"/></div>
   </aside>
   <main class="main-column">
    <section class="panel editor"><template v-if="ids.length"><div class="editing-heading"><div><small>当前正在维护</small><h2>{{currentNames}}</h2><p>{{ids.length>1?`已明确选择 ${ids.length} 个实际 SKU，共同修改仅作用于这些规格。`:saleLabel(store.data,ids[0]!).spec}}</p></div><el-tag>{{dirty?'有未保存修改':'当前已保存资料'}}</el-tag></div>
     <p v-if="!allAccessories" class="notice">此处维护配件适用设备。当前选择含设备或其他商品，可使用下方实际设备查询；请在左侧选择配件 SKU。</p>
     <el-form v-else label-position="top" :disabled="!canEdit||busy"><h3>明确型号</h3><p class="muted">新选型号共用一份依据；已有其他来源和规格限制在下方分别维护。</p>
      <DeviceModelMultiSelect v-model="keys" :data="store.data" :disabled="!canEdit||busy"/>
      <div class="common-fields"><el-form-item label="本次新增型号结论"><el-select v-model="common.conclusion" aria-label="明确型号结论"><el-option value="compatible" label="适用"/><el-option value="incompatible" label="明确不适用"/></el-select></el-form-item><el-form-item label="核验状态"><el-select v-model="common.verification" aria-label="明确型号核验状态"><el-option value="confirmed" label="已核验"/><el-option value="pending" label="待核验"/></el-select></el-form-item><el-form-item label="能力"><el-select :model-value="common.capability" aria-label="明确型号能力" @change="changeCapability($event)"><el-option value="basic" label="基本使用"/><el-option value="fast-charge" label="快充"/><el-option value="other" label="其他"/></el-select></el-form-item></div>
      <el-form-item label="本次共同依据（填写一次）"><el-input v-model="common.source" type="textarea" :rows="2" aria-label="明确型号共同依据" placeholder="供应商资料或人工核对结果；新增型号共用，既有来源保留"/></el-form-item>
      <el-form-item label="取消已选型号时"><el-radio-group v-model="removal"><el-radio value="remove">删除声明，回到没有确认依据</el-radio><el-radio value="deny">明确改为不适用</el-radio></el-radio-group></el-form-item>
      <el-collapse v-model="openSections"><el-collapse-item title="通用适用条件（可与明确型号同时存在）" name="general"><p class="muted">符合必要条件的新型号可动态命中，不需要重复逐型号绑定。</p><article v-for="(g,i) in generalRows" :key="g.key" class="general-card"><div class="section-heading"><strong>{{g.id?'已有通用依据':'新增通用依据'}} · {{typeName(familyProductTypeId(store.data,g.draft.skuId))}}</strong><el-button text type="danger" :disabled="!canDelete&&!!g.id" @click="generalRows.splice(i,1)">移除此条</el-button></div><GeneralClaimEditor v-model="g.draft" :data="store.data"/></article><el-button :disabled="!canCreate" data-add-general @click="addGeneral">添加通用适用条件</el-button></el-collapse-item>
      <el-collapse-item :title="`已有型号与规格声明（${existingLinks.length} 条）`" name="existing"><p class="muted">不同来源独立保存；取消勾选与明确不适用含义不同。历史规格限制和必要条件会保留。</p><article v-for="row in existingLinks" :key="row.id" class="existing-row"><template v-if="!removed.includes(row.id)"><div class="section-heading"><strong>{{hostLabel(row.host)}} <small>{{row.host.scope==='planning'?'仅指定规格':''}}</small></strong><el-tag>{{declarationLabel(edits[row.id]?{...row,...edits[row.id]}:row)}}</el-tag></div><p>{{row.source||row.note||'历史资料未记录依据'}}</p><div v-if="editingId===row.id&&edits[row.id]" class="edit-existing"><el-select v-model="edits[row.id]!.conclusion" aria-label="编辑型号结论"><el-option value="compatible" label="适用"/><el-option value="conditional" label="条件适用"/><el-option value="incompatible" label="明确不适用"/></el-select><el-select v-model="edits[row.id]!.verification" aria-label="编辑型号核验"><el-option value="confirmed" label="已核验"/><el-option value="pending" label="待核验"/></el-select><el-input v-model="edits[row.id]!.source" aria-label="编辑型号依据" placeholder="资料依据"/><p v-if="row.conditions?.length" class="muted">已有 {{row.conditions.length}} 项必要条件按原记录保留。</p></div><el-button v-if="canUpdate" text @click="editExplicit(row)">编辑此条</el-button><el-button v-if="canDelete" text type="danger" @click="removeExplicit(row)">删除此声明</el-button><details><summary>身份与来源详情</summary><p>{{row.id}} · {{row.host.productModelId}} · {{row.host.planningId||'型号范围'}}</p></details></template><p v-else>此声明将在保存时删除 <el-button link @click="removed=removed.filter(id=>id!==row.id)">撤销移除</el-button></p></article></el-collapse-item></el-collapse>
     </el-form>
     <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
     <div v-if="allAccessories" class="save-actions"><span class="muted">{{changes.length}} 项型号变更 · {{generalChanges.length}} 项通用变更</span><el-button :disabled="busy||!dirty" @click="discardEditing">放弃修改</el-button><el-button v-if="canEdit" type="primary" :loading="busy" :disabled="!dirty||!staged.ok||!changes.length&&!generalChanges.length" data-save-compat @click="save">保存适用资料</el-button></div>
    </template><el-empty v-else description="从左侧选择商品，维护适用设备"/></section>
    <section class="panel preview"><div class="section-heading"><h2>结果预览</h2><el-radio-group v-model="previewMode"><el-radio-button value="draft">未保存预览</el-radio-button><el-radio-button value="saved">当前已保存结果</el-radio-button></el-radio-group></div><CompatibilityDeviceSelect v-model="previewDevice" :data="store.data"/>
     <el-alert v-if="previewMode==='draft'&&dirty&&!staged.ok" :title="staged.message" type="warning" :closable="false"/>
     <p v-else-if="!previewDevice" class="muted">选择一个实际设备，按正式查询核对必要条件与销售准入。</p>
     <template v-else><el-alert v-if="previewQuery.device?.status!=='resolved'" :title="previewQuery.device?.message||'设备无法识别，请完善明确型号及来源资料'" type="warning" :closable="false"/><article v-for="id in ids" :key="id" class="preview-row"><div class="section-heading"><strong>{{saleLabel(store.data,id).name}}</strong><el-tag :type="previewQuery.candidates.some(c=>c.id===id)?'success':'warning'">{{previewQuery.candidates.some(c=>c.id===id)?'可正常选购':'不能进入正常候选'}}</el-tag></div><p>{{previewQuery.groups.flatMap(g=>g.diagnostics).find(d=>d.id===id)?.reason||'基本使用依据与销售状态已通过正式查询'}}</p><CompatibilityEvidence :evidence="previewMatch(id)?.evidence||[]"/></article></template>
    </section>
   </main>
  </div>
  <section v-else class="panel reverse"><h2>按设备查询可用商品</h2><CompatibilityDeviceSelect v-model="previewDevice" :data="store.data"/><p class="muted">读取当前已保存资料；实际设备包含规格事实，仅选择型号时缺失的条件保持待核验。</p><el-radio-group v-model="reverseMode"><el-radio-button value="sales">已确认适用且可售</el-radio-button><el-radio-button value="diagnostics">待核验 / 不适用 / 资料问题</el-radio-button></el-radio-group><el-alert v-if="reverseQuery.device&&reverseQuery.device.status!=='resolved'" :title="reverseQuery.device.message" type="warning" :closable="false"/>
   <section v-for="g in reverseQuery.groups.filter(g=>reverseMode==='sales'?g.candidates.length:g.diagnostics.length)" :key="g.id" class="reverse-group"><h3>{{g.name}}</h3><article v-for="r in reverseMode==='sales'?g.candidates:g.diagnostics" :key="r.id" class="reverse-row"><div><strong>{{r.name}}</strong><p>{{'reason' in r?r.reason:r.spec}}</p></div><el-button v-if="canEdit" link @click="locate(r.id)">维护适用设备</el-button></article></section><el-empty v-if="!previewDevice||!(reverseMode==='sales'?reverseQuery.candidates.length:reverseQuery.groups.some(g=>g.diagnostics.length))" :description="previewDevice?'当前视角暂无结果':'请选择实际设备或明确型号'"/>
  </section>
 </div>
</template>
<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate,type LocationQuery} from 'vue-router'
import {ElMessageBox,ElMessage} from 'element-plus'
import PageHead from '../components/PageHead.vue'
import CatalogScopeTree from '../components/catalog-workspace/CatalogScopeTree.vue'
import DeviceModelMultiSelect from '../components/compatibility/DeviceModelMultiSelect.vue'
import GeneralClaimEditor from '../components/compatibility/GeneralClaimEditor.vue'
import CompatibilityDeviceSelect from '../components/compatibility/CompatibilityDeviceSelect.vue'
import CompatibilityEvidence from '../components/compatibility/CompatibilityEvidence.vue'
import {useCatalogStore} from '../stores/catalog'
import {buildCatalogWorkspaceIndex} from '../domain/catalogWorkspaceQuery'
import {categoryChain} from '../domain/categoryTree'
import {isRealSku} from '../domain/catalogIdentity'
import {familyProductTypeId} from '../domain/productIdentity'
import {saleLabel,saleQuery,deviceFromKey} from '../domain/benefitSales/query'
import {hostLabel} from '../domain/compatibility'
import {cloneRecord} from '../domain/recordCopy'
import {internalReturnLocation} from '../domain/internalNavigation'
import {compatibilityWorkspaceBasis,selectedModelKeys,modelSelectionChanges,previewWorkspace,mergeModelChanges,skuDeclarations,declarationLabel} from '../domain/compatibilityWorkspace'
import {queryAccessoryDevices} from '../domain/accessoryCompatibilityQuery'
import {declarationDraft,type DeclarationDraft} from '../domain/accessoryCompatibilityCommands'
import type {GeneralDraft,GeneralChange} from '../domain/generalCompatibility'
import type {CompatibilityLink} from '../domain/types'
const store=useCatalogStore(),route=useRoute(),router=useRouter(),view=ref('products'),ids=ref<string[]>([]),category=ref(''),typeId=ref(''),expanded=ref<string[]>([]),search=ref(''),includeDevices=ref(false),busy=ref(false),error=ref(''),keys=ref<string[]>([]),originalKeys=ref<string[]>([]),basis=ref(''),savedForm=ref(''),previewDevice=ref(''),previewMode=ref('draft'),reverseMode=ref('sales'),openSections=ref<string[]>([]),removal=ref<'remove'|'deny'>('remove')
const common=ref({source:'',verification:'confirmed' as DeclarationDraft['verification'],conclusion:'compatible' as DeclarationDraft['conclusion'],capability:'basic' as DeclarationDraft['capability']}),edits=ref<Record<string,DeclarationDraft>>({}),removed=ref<string[]>([]),editingId=ref('')
type GeneralRow={key:string;id?:string;revision:number;draft:GeneralDraft}
const generalRows=ref<GeneralRow[]>([]),originalGeneral=ref<GeneralRow[]>([])
const canCreate=computed(()=>store.can('product:compatibility:create')),canUpdate=computed(()=>store.can('product:compatibility:update')),canDelete=computed(()=>store.can('product:compatibility:delete')),canEdit=computed(()=>canCreate.value||canUpdate.value||canDelete.value),index=computed(()=>buildCatalogWorkspaceIndex(store.data,store.can)),returnTo=computed(()=>internalReturnLocation(route.query.returnTo))
const typeName=(id:string)=>store.data.productTypes.find(t=>t.id===id)?.name||'未指定类型'
const ledgerHealth=computed(()=>new Map(store.data.skus.filter(s=>isRealSku(store.data,s)&&store.data.productTypes.find(t=>t.id===familyProductTypeId(store.data,s.familyId))?.catalogRole==='accessory').map(s=>{const q=queryAccessoryDevices(store.data,{kind:'sku',id:s.id});return [s.id,{invalid:q.issues.length,conflict:q.hosts.some(h=>h.conflict)||q.generalDevices?.some(d=>d.capabilities.some(c=>c.conflict))}]})))
const products=computed(()=>store.data.skus.filter(s=>isRealSku(store.data,s)).map(s=>{const f=store.data.families.find(f=>f.id===s.familyId)!,type=familyProductTypeId(store.data,f.id),links=skuDeclarations(store.data,s.id),general=(store.data.generalCompatibilityClaims||[]).filter(c=>c.skuId===s.id);return {invalid:ledgerHealth.value.get(s.id)?.invalid||0,conflict:ledgerHealth.value.get(s.id)?.conflict||false,id:s.id,familyId:f.id,familyName:f.name,categoryId:f.categoryId,type,typeName:typeName(type),...saleLabel(store.data,s.id),status:s.status==='on_sale'&&f.shelfStatus==='online'?'在售':'非在售',confirmed:new Set(links.filter(l=>l.verification==='confirmed'&&l.conclusion!=='incompatible').map(l=>l.host.identityKey)).size,pending:links.filter(l=>l.verification!=='confirmed').length+general.filter(g=>g.verification!=='confirmed').length,count:links.length+general.length}}).filter(r=>(includeDevices.value||store.data.productTypes.find(t=>t.id===r.type)?.catalogRole==='accessory')&&(!typeId.value||r.type===typeId.value)&&(!category.value||categoryChain(store.data.categories,r.categoryId).some(c=>c.id===category.value))&&`${r.name} ${r.spec} ${r.code} ${r.typeName}`.toLowerCase().includes(search.value.trim().toLowerCase())))
const productGroups=computed(()=>{const groups=new Map<string,{id:string;name:string;rows:typeof products.value}>();for(const r of products.value){if(!groups.has(r.familyId))groups.set(r.familyId,{id:r.familyId,name:r.familyName,rows:[]});groups.get(r.familyId)!.rows.push(r)}return [...groups.values()]})
const currentNames=computed(()=>ids.value.map(id=>saleLabel(store.data,id).name).join('、')),allAccessories=computed(()=>ids.value.length>0&&ids.value.every(id=>{const s=store.data.skus.find(s=>s.id===id);return s&&store.data.productTypes.find(t=>t.id===familyProductTypeId(store.data,s.familyId))?.catalogRole==='accessory'}))
const existingLinks=computed(()=>ids.value.flatMap(id=>skuDeclarations(store.data,id)))
const changes=computed(()=>mergeModelChanges(modelSelectionChanges(store.data,ids.value,originalKeys.value,keys.value,removal.value,common.value),edits.value,removed.value))
const generalChanges=computed<GeneralChange[]>(()=>{const result:GeneralChange[]=[];for(const old of originalGeneral.value)if(!generalRows.value.some(r=>r.id===old.id))result.push({kind:'remove',id:old.id!,revision:old.revision});for(const row of generalRows.value){const old=originalGeneral.value.find(r=>r.id===row.id);if(row.id&&old){if(JSON.stringify(row.draft)!==JSON.stringify(old.draft))result.push({kind:'edit',id:row.id,revision:row.revision,draft:row.draft})}else result.push({kind:'add',draft:row.draft})}return result})
const formStamp=()=>JSON.stringify([keys.value,common.value,removal.value,edits.value,removed.value,generalRows.value]),dirty=computed(()=>!!savedForm.value&&savedForm.value!==formStamp()),staged=computed(()=>previewWorkspace(store.data,changes.value,generalChanges.value))
function query(data:typeof store.data){return saleQuery(data,{mode:'free',categoryId:'',productTypeIds:data.productTypes.filter(t=>t.catalogRole==='accessory'&&t.status==='enabled').map(t=>t.id),device:deviceFromKey(previewDevice.value)})}
const previewQuery=computed(()=>query(previewMode.value==='draft'&&staged.value.ok?staged.value.candidate:store.data)),reverseQuery=computed(()=>query(store.data))
function previewMatch(id:string){const q=previewQuery.value.compatibility;return [...q?.sales||[],...q?.pending||[],...q?.excluded||[],...q?.unavailable||[]].find(m=>m.sku.id===id)}
function load(targets:string[]){ids.value=targets.filter(id=>store.data.skus.some(s=>s.id===id&&isRealSku(store.data,s)));originalKeys.value=selectedModelKeys(store.data,ids.value);keys.value=[...originalKeys.value];basis.value=compatibilityWorkspaceBasis(store.data);common.value={source:'',verification:'confirmed',conclusion:'compatible',capability:'basic'};edits.value={};removed.value=[];editingId.value='';removal.value='remove';error.value='';generalRows.value=(store.data.generalCompatibilityClaims||[]).filter(g=>ids.value.includes(g.skuId)).map(({id,revision,createdAt:_c,updatedAt:_u,...draft})=>({key:id,id,revision,draft:cloneRecord(draft)}));originalGeneral.value=cloneRecord(generalRows.value);savedForm.value=formStamp()}
async function canLeave(){if(busy.value)return false;if(!dirty.value)return true;try{await ElMessageBox.confirm('适用资料尚未保存，放弃本次修改？','未保存修改',{confirmButtonText:'放弃修改',cancelButtonText:'继续编辑',closeOnClickModal:false});return true}catch{return false}}
async function choose(targets:string[]){if(JSON.stringify(targets)===JSON.stringify(ids.value)||!await canLeave())return;load(targets)}
async function changeView(next:string){if(next===view.value)return;if(!await canLeave())return;load(ids.value);view.value=next}
async function locate(id:string){if(!await canLeave())return;load([id]);view.value='products'}
function changeCapability(capability:DeclarationDraft['capability']){if(JSON.stringify(keys.value)!==JSON.stringify(originalKeys.value)){error.value='请先保存或放弃尚未保存的型号选择，再切换能力。';return}common.value.capability=capability;originalKeys.value=selectedModelKeys(store.data,ids.value,capability);keys.value=[...originalKeys.value]}
function addGeneral(){for(const id of ids.value)generalRows.value.push({key:`new-${id}-${Date.now()}-${generalRows.value.length}`,revision:0,draft:{skuId:id,deviceTypeIds:[],capability:'basic',conditions:[],conclusion:'conditional',verification:'pending',source:'',note:''}})}
function editExplicit(row:CompatibilityLink){if(!edits.value[row.id])edits.value[row.id]=declarationDraft(row);editingId.value=row.id}
function removeExplicit(row:CompatibilityLink){removed.value=[...new Set([...removed.value,row.id])]}
async function discardEditing(){if(await canLeave())load(ids.value)}
async function save(){if(busy.value||!dirty.value)return;const actor=store.activeUserId,preview=store.previewUserId;busy.value=true;error.value='';try{const result=await store.saveCompatibilityWorkspace(changes.value,generalChanges.value,basis.value,()=>actor===store.activeUserId&&preview===store.previewUserId);if(actor!==store.activeUserId||preview!==store.previewUserId)return;if(!result.ok){error.value=result.message||'保存失败，输入保留';return}load(ids.value);ElMessage.success('适用资料已保存')}catch(e){if(actor===store.activeUserId&&preview===store.previewUserId)error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
function entrance(q:LocationQuery){view.value=q.tab==='device'||q.deviceView==='1'?'device':'products';const targets=typeof q.skuIds==='string'?q.skuIds.split(','):typeof q.targetId==='string'?[q.targetId]:typeof q.sku==='string'?[q.sku]:typeof q.spu==='string'?store.data.skus.filter(s=>s.familyId===q.spu&&isRealSku(store.data,s)).map(s=>s.id):[];load(targets);previewDevice.value=typeof q.device==='string'?`sku:${q.device}`:typeof q.deviceModel==='string'?`model:${q.deviceModel}`:''}
entrance(route.query)
onBeforeRouteLeave(canLeave);onBeforeRouteUpdate(async to=>{if(!await canLeave())return false;entrance(to.query);return true})
watch(()=>[store.activeUserId,store.previewUserId],()=>{load([]);previewDevice.value='';error.value='身份已切换，请重新选择商品'})
function unload(e:BeforeUnloadEvent){if(dirty.value||busy.value){e.preventDefault();e.returnValue=''}}
window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>window.removeEventListener('beforeunload',unload))
